SELECT count(*) FROM issues i WHERE i.project_id = ANY (:VIS) AND (NOT i.is_private OR i.author_id = :ME) AND EXISTS (SELECT 1 FROM issue_cf c WHERE c.issue_id = i.id AND c.field_id = 3 AND c.v_ref = oid_(3,0)) AND EXISTS (SELECT 1 FROM issue_cf c WHERE c.issue_id = i.id AND c.field_id = 800 AND c.v_num BETWEEN 1000 AND 5000);
